input.new_string:
let spent = out.join('\n').length;
let budgetedOut = 0;

for (const [pack, { files, newCheckIds }] of entries) {
  out.push(`## ${pack}`, '');
  if (newCheckIds.length) {
    out.push(`**New checks** (a check covers a local item more strongly than prose): ${newCheckIds.map((id) => `\`${id}\``).join(', ')}`, '');
  }
  for (const [path, file] of Object.entries(files)) {
    out.push(`### \`${path}\``, '');
    if (file.patchUnavailable) {
      out.push('The API returned no patch for this file (too large a diff) — read the file whole.', '');
      continue;
    }
    if (!file.added.length) { out.push('_Removals only — nothing added here to prune against._', ''); continue; }

    const shown = file.added.slice(0, MAX_ADDED_LINES_PER_FILE);
    const block = ['```', ...shown, '```', ''];
    const cost = block.join('\n').length;
    if (spent + cost > MAX_BRIEF_BYTES) { budgetedOut += 1; out.push('_(additions omitted — see the note at the end)_', ''); continue; }
    spent += cost;
    out.push(...block);
    const rest = file.added.length - shown.length;
    if (rest > 0) out.push(`_…and ${rest} more added line${rest === 1 ? '' : 's'} in this file — read its diff for the rest._`, '');
  }
}
if (budgetedOut) {
  out.push(
    '---', '',
    `**This brief hit its size budget**: additions for ${budgetedOut} further file${budgetedOut === 1 ? '' : 's'} are not shown.`,
    'Every changed file is named above — read the diff of the omitted ones directly.', '',
  );
}
return out.join('\n') + '\n';

