+
+/** The lines a unified-diff patch ADDED, marker stripped. */
+export function addedLines(patch) {
+  if (typeof patch !== 'string') return [];
+  return patch.split('\n')
+    .filter((l) => l.startsWith('+') && !l.startsWith('+++'))
+    .map((l) => l.slice(1));
